using Avalonia;

namespace DatabasesLab;

/// <summary>
/// dotnet run            opens the window
/// dotnet run -- check   prints the lab check
/// On GitHub there is no screen, so the check runs by itself.
/// </summary>
internal static class Program
{
    [STAThread]
    public static void Main(string[] args)
    {
        bool askedForCheck = args.Length > 0 && args[0] == "check";
        bool onGitHub = Environment.GetEnvironmentVariable("GITHUB_ACTIONS") == "true";

        if (askedForCheck || onGitHub)
        {
            LabCheck.Run();
        }
        else
        {
            BuildAvaloniaApp().StartWithClassicDesktopLifetime(args);
        }
    }

    public static AppBuilder BuildAvaloniaApp()
    {
        return AppBuilder.Configure<App>()
            .UsePlatformDetect()
            .WithInterFont()
            .LogToTrace();
    }
}
